import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const baseBook: Book = {
  id: 'book-1',
  title: 'The Great Gatsby',
  author: 'F. Scott Fitzgerald',
  status: 'to-read',
};

describe('BookCard', () => {
  it('renders the book title', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'The Great Gatsby' })).toBeDefined();
  });

  it('renders the book author', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByText('F. Scott Fitzgerald')).toBeDefined();
  });

  it('renders the status badge with the book status text', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    expect(screen.getByText('to-read')).toBeDefined();
  });

  it('sets data-status attribute on badge to the book status', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    const badge = screen.getByText('to-read');
    expect(badge.getAttribute('data-status')).toBe('to-read');
  });

  it('calls onClick with book id when clicked', () => {
    const onClick = vi.fn();
    render(<BookCard book={baseBook} onClick={onClick} />);
    fireEvent.click(screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' }));
    expect(onClick).toHaveBeenCalledWith('book-1');
    expect(onClick).toHaveBeenCalledTimes(1);
  });

  it('calls onClick with book id when Enter key is pressed', () => {
    const onClick = vi.fn();
    render(<BookCard book={baseBook} onClick={onClick} />);
    fireEvent.keyDown(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' }),
      { key: 'Enter' }
    );
    expect(onClick).toHaveBeenCalledWith('book-1');
    expect(onClick).toHaveBeenCalledTimes(1);
  });

  it('does not call onClick when a non-Enter key is pressed', () => {
    const onClick = vi.fn();
    render(<BookCard book={baseBook} onClick={onClick} />);
    fireEvent.keyDown(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' }),
      { key: ' ' }
    );
    expect(onClick).not.toHaveBeenCalled();
  });

  it('aria-label includes title and author', () => {
    render(<BookCard book={baseBook} onClick={vi.fn()} />);
    const card = screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' });
    expect(card.getAttribute('aria-label')).toBe('The Great Gatsby by F. Scott Fitzgerald');
  });

  it('data-status reflects the current status value', () => {
    const readingBook: Book = { ...baseBook, status: 'reading' };
    render(<BookCard book={readingBook} onClick={vi.fn()} />);
    expect(screen.getByText('reading').getAttribute('data-status')).toBe('reading');
  });
});

