import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChipBar } from './ChipBar';

const chips = ['to-read', 'reading', 'read'];

describe('ChipBar', () => {
  it('renders a button for each chip', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'to-read' })).toBeDefined();
    expect(screen.getByRole('button', { name: 'reading' })).toBeDefined();
    expect(screen.getByRole('button', { name: 'read' })).toBeDefined();
  });

  it('unselected chips have aria-pressed="false"', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'to-read' }).getAttribute('aria-pressed')).toBe('false');
  });

  it('selected chips have aria-pressed="true"', () => {
    render(<ChipBar chips={chips} selected={['reading']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'reading' }).getAttribute('aria-pressed')).toBe('true');
    expect(screen.getByRole('button', { name: 'to-read' }).getAttribute('aria-pressed')).toBe('false');
  });

  it('clicking an unselected chip calls onSelectionChange with it added', () => {
    const onSelectionChange = vi.fn();
    render(<ChipBar chips={chips} selected={['reading']} onSelectionChange={onSelectionChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'to-read' }));
    expect(onSelectionChange).toHaveBeenCalledWith(['reading', 'to-read']);
    expect(onSelectionChange).toHaveBeenCalledTimes(1);
  });

  it('clicking a selected chip calls onSelectionChange with it removed', () => {
    const onSelectionChange = vi.fn();
    render(<ChipBar chips={chips} selected={['reading', 'read']} onSelectionChange={onSelectionChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'reading' }));
    expect(onSelectionChange).toHaveBeenCalledWith(['read']);
    expect(onSelectionChange).toHaveBeenCalledTimes(1);
  });

  it('toggling the only selected chip calls onSelectionChange with empty array', () => {
    const onSelectionChange = vi.fn();
    render(<ChipBar chips={chips} selected={['to-read']} onSelectionChange={onSelectionChange} />);
    fireEvent.click(screen.getByRole('button', { name: 'to-read' }));
    expect(onSelectionChange).toHaveBeenCalledWith([]);
  });

  it('renders no buttons when chips array is empty', () => {
    render(<ChipBar chips={[]} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.queryAllByRole('button')).toHaveLength(0);
  });
});

