import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, waitFor } from '@testing-library/react';
import { useBooks } from './useBooks';
import * as api from '../api';
import type { Book } from '../types';

const mockBooks: Book[] = [
  { id: '1', title: 'Dune', author: 'Frank Herbert', status: 'read' },
  { id: '2', title: 'Neuromancer', author: 'William Gibson', status: 'to-read' },
];

describe('useBooks', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('starts in loading state before getBooks resolves', () => {
    // never-resolving promise keeps loading=true for the duration of this assertion
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(() => {}));
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('transitions to loaded state with data after getBooks resolves', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue(mockBooks);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data).toEqual(mockBooks);
    expect(result.current.error).toBeNull();
  });

  it('sets data to empty array when getBooks resolves with no books', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue([]);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.data).toEqual([]);
    expect(result.current.error).toBeNull();
  });

  it('transitions to error state when getBooks rejects', async () => {
    const err = new Error('fetch failed');
    vi.spyOn(api, 'getBooks').mockRejectedValue(err);
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBe(err);
    expect(result.current.data).toBeNull();
  });
});

